const update = $json.body ?? $json;
const callback = update.callback_query;
const message = update.message;
const user = callback?.from ?? message?.from;
const chat = callback?.message?.chat ?? message?.chat;
if (!user || !chat) return [];
if (callback) {
  const match = /^(aiok|aino):([a-f0-9]{12}):([A-Za-z0-9_-]{10,})$/.exec(callback.data ?? '');
  if (!match) return [];
  return [{ json: { route: match[1] === 'aiok' ? 'approve' : 'deny', plan_id: match[2], approval_token: match[3], chat_id: chat.id, user_id: user.id, callback_query_id: callback.id } }];
}
const text = String(message?.text ?? '').trim();
const command = /^\/fix(?:@\w+)?(?:\s+([\s\S]+))?$/i.exec(text);
if (!command || !command[1]?.trim()) return [{ json: { route: 'help', chat_id: chat.id, user_id: user.id, text: 'Usa /fix seguito dalla descrizione del problema. Non inserire password, token o dati privati.' } }];
return [{ json: { route: 'diagnose', chat_id: chat.id, user_id: user.id, prompt: command[1].trim().slice(0, 4000) } }];

const request = $('Route Telegram Update').first().json;
const diagnostics = $json.error ? { generated_at: Math.floor(Date.now() / 1000), policy: { restartable_systemd_units: [], restartable_compose_services: [], maintenance_tasks: [] }, diagnostic_error: String($json.error.message ?? $json.error).slice(0, 500) } : $json;
const snapshot = { generated_at: diagnostics.generated_at, policy: diagnostics.policy, systemd: diagnostics.systemd, compose: diagnostics.compose, git: diagnostics.git, disk: diagnostics.disk, diagnostic_error: diagnostics.diagnostic_error };
return [{ json: { ...request, diagnostics: snapshot, llm_input: JSON.stringify({ richiesta: request.prompt.slice(0, 1200), snapshot }) } }];

const request = $('Route Telegram Update').first().json;
const diagnostics = $('Prepara contesto Qwen').first().json.diagnostics;
let plan;
try {
  if ($json.error) throw new Error(String($json.error.message ?? $json.error).slice(0, 500));
  const candidate = $json.output ?? $json;
  plan = typeof candidate === 'string' ? JSON.parse(candidate) : candidate;
  for (const key of ['summary', 'problem']) if (typeof plan?.[key] !== 'string') throw new Error('Piano Qwen non valido: ' + key);
  for (const key of ['evidence', 'actions', 'risks', 'verification']) if (!Array.isArray(plan[key]) || !plan[key].every(v => key === 'actions' ? typeof v === 'object' && v !== null : typeof v === 'string')) throw new Error('Piano Qwen non valido: ' + key);
  for (const key of ['evidence', 'risks', 'verification']) plan[key] = plan[key].slice(0, 8);
} catch (error) {
  plan = { summary: 'Diagnosi non completata', problem: 'Qwen locale non ha completato correttamente la richiesta.', evidence: [String(error.message ?? error).slice(0, 500)], actions: [], risks: ['Nessuna azione è stata registrata o eseguita.'], verification: ['Controllare i log di n8n e Ollama, poi riprovare.'] };
}
const allowed = { restart_systemd_unit: new Set(diagnostics.policy.restartable_systemd_units ?? []), restart_compose_service: new Set(diagnostics.policy.restartable_compose_services ?? []), run_maintenance_task: new Set(diagnostics.policy.maintenance_tasks ?? []) };
const invalidAction = plan.actions.length > 3 || plan.actions.some(action => Object.keys(action).sort().join(',') !== 'rationale,target,type' || typeof action.rationale !== 'string' || !allowed[action.type]?.has(action.target));
if (invalidAction) { plan.actions = []; plan.evidence.push('Il modello ha proposto almeno un’azione fuori policy: il piano è stato bloccato.'); plan.risks.push('Nessuna azione è stata registrata o eseguita.'); }
const lines = ['DIAGNOSI QWEN LOCALE - nessuna modifica ancora eseguita', '', 'Sintesi: ' + plan.summary, '', 'Problema individuato:', plan.problem, '', 'Evidenze:', ...(plan.evidence.length ? plan.evidence.map((v, i) => (i + 1) + '. ' + v) : ['Nessuna evidenza conclusiva.']), '', 'Azioni proposte:'];
if (!plan.actions.length) lines.push('Nessuna azione eseguibile proposta.');
else plan.actions.forEach((action, i) => { lines.push((i + 1) + '. ' + action.type + ' -> ' + action.target); lines.push('   Motivo: ' + action.rationale); });
lines.push('', 'Rischi:', ...(plan.risks.length ? plan.risks.map((v, i) => (i + 1) + '. ' + v) : ['Nessun rischio aggiuntivo dichiarato.']), '', 'Verifica prevista:', ...(plan.verification.length ? plan.verification.map((v, i) => (i + 1) + '. ' + v) : ['Nuova diagnostica dopo l’esecuzione.']));
return [{ json: { ...request, plan, has_actions: plan.actions.length > 0 ? 'yes' : 'no', report: lines.join('\n') } }];

const registration = $json;
const parsed = $('Analizza piano').first().json;
return [{ json: { chat_id: parsed.chat_id, text: parsed.report + '\n\nIl piano scade tra 15 minuti. Confermi l’esecuzione?', inline_keyboard: [[{ text: 'Conferma azioni', callback_data: registration.approve_callback }, { text: 'Annulla', callback_data: registration.reject_callback }]] } }];

const route = $('Route Telegram Update').first().json;
const execution = $('Esegui piano').first().json;
const diagnostics = $json;
const lines = [execution.status === 'completed' ? 'ESECUZIONE COMPLETATA' : 'ESECUZIONE NON COMPLETATA', 'Piano: ' + execution.id, 'Stato: ' + execution.status, ''];
for (const [index, result] of (execution.results ?? []).entries()) { lines.push((index + 1) + '. ' + result.type + ' -> ' + result.target); lines.push('   Esito: ' + (result.ok ? 'OK' : 'ERRORE')); if (result.output) lines.push('   Output: ' + String(result.output).slice(0, 4000)); }
lines.push('', 'Controllo successivo: nuova diagnostica acquisita.');
for (const [stack, value] of Object.entries(diagnostics.compose ?? {})) if (!value.ok) lines.push(stack + ': diagnostica Compose non riuscita');
return [{ json: { chat_id: route.chat_id, text: lines.join('\n') } }];
